import React, { useState } from 'react';
import './App.css';
import UserTypeSelection from './components/UserTypeSelection';
import LoginForm from './components/LoginForm';
import SignupForm from './components/SignupForm';
import BudgetPreference from './components/BudgetPreference';
import LocationPreference from './components/LocationPreference';
import SleepSchedule from './components/SleepSchedule';

function App() {
  const [currentView, setCurrentView] = useState('selection');
  const [userType, setUserType] = useState(null);
  const [userPreferences, setUserPreferences] = useState({
    budget: null,
    location: null,
    sleepSchedule: null,
    numRoommates: null
  });

  // Single handleNext function that progresses through the flow
  const handleNext = () => {
    const flow = [
      'selection',
      'login', 
      'signup-selection',
      'signup',
      'budget-preference',
      'location-preference',
      'sleep-schedule'
    ];
    
    const currentIndex = flow.indexOf(currentView);
    if (currentIndex < flow.length - 1) {
      setCurrentView(flow[currentIndex + 1]);
    }
  };

  // Or even simpler - just hardcode the transitions
  const handleNextSimple = () => {
    switch(currentView) {
      case 'selection': setCurrentView('login'); break;
      case 'login': setCurrentView('signup-selection'); break;
      case 'signup-selection': setCurrentView('signup'); break;
      case 'signup': setCurrentView('budget-preference'); break;
      case 'budget-preference': setCurrentView('location-preference'); break;
      case 'location-preference': setCurrentView('sleep-schedule'); break;
      case 'sleep-schedule': setCurrentView('selection'); break; // or 'complete'
      default: setCurrentView('selection');
    }
  };

  const handleUserTypeSelect = (type) => {
    setUserType(type);
    handleNext(); // Automatically go to next view
  };

  const handleShowSignup = () => {
    setCurrentView('signup-selection');
  };

  const handleSignupTypeSelect = (type) => {
    setUserType(type);
    handleNext(); // Automatically go to next view
  };

  const handleBackToSelection = () => {
    setCurrentView('selection');
    setUserType(null);
  };

  const handleBackToLogin = () => {
    setCurrentView('login');
  };

  const handleBackToSignupSelection = () => {
    setCurrentView('signup-selection');
    setUserType(null);
  };

  const renderCurrentView = () => {
    switch (currentView) {
      case 'selection':
        return (
          <UserTypeSelection
            onUserTypeSelect={handleUserTypeSelect}
            onShowSignup={handleShowSignup}
            mode="login"
          />
        );
      case 'login':
        return (
          <LoginForm
            userType={userType}
            onBack={handleBackToSelection}
            onShowSignup={handleShowSignup}
            onNext={handleNext}
          />
        );
      case 'signup-selection':
        return (
          <UserTypeSelection
            onUserTypeSelect={handleSignupTypeSelect}
            onBack={handleBackToSelection}
            mode="signup"
          />
        );
      case 'signup':
        return (
          <SignupForm
            userType={userType}
            onBack={handleBackToSignupSelection}
            onShowLogin={handleBackToLogin}
            onNext={handleNext}
          />
        );
      case 'budget-preference':
        return(
          <BudgetPreference
            onNext={handleNext}
            userPreferences={userPreferences}
            setUserPreferences={setUserPreferences}
          />
        );
      case 'location-preference':
        return(
            <LocationPreference
              onNext={handleNext}
              userPreferences={userPreferences}
              setUserPreferences={setUserPreferences}
          />
        );
      case 'sleep-schedule':
        return (
          <SleepSchedule
            onNext={handleNext}
            userPreferences={userPreferences}
            setUserPreferences={setUserPreferences}
          />
        );
      default:
        return (
          <UserTypeSelection
            onUserTypeSelect={handleUserTypeSelect}
            onShowSignup={handleShowSignup}
            mode="login"
          />
        );
    }
  };

  return (
    <div className="container">
      {/* Decorative elements */}
      <div className="decoration top-right">
        <div className="wave wave-1"></div>
        <div className="wave wave-2"></div>
        <div className="wave wave-3"></div>
      </div>

      <div className="decoration bottom-left">
        <div className="wave wave-1"></div>
        <div className="wave wave-2"></div>
        <div className="wave wave-3"></div>
      </div>

      {/* Main content */}
      <div className="login-content">
        <div className="logo">
          <h1>Reelty</h1>
          <p>Your Property Journey Starts Here</p>
        </div>

        {renderCurrentView()}
      </div>
    </div>
  );
}

export default App;
